import { Component, CommonModule } from '@angular/core';

// Create the AccordionComponent class with @Component decorator here
@Component({
  selector: 'app-accordion',
  standalone: true,
  imports: [CommonModule],
  template: `
    <div class="accordion">
      <div *ngFor="let item of accordionItems; let i = index" class="accordion-item">
        <div class="accordion-header" (click)="toggle(i)">
          <h3>{{ item.title }}</h3>
        </div>
        <!-- Add content section here -->
      </div>
    </div>
  `
})
export class AccordionComponent {
  // Define the AccordionItem interface here
  interface AccordionItem {
    title: string;
    content: string;
    expanded: boolean;
  }

  // Initialize the accordion items array here
  accordionItems: AccordionItem[] = [
    { title: 'First Item', content: 'Content for first item', expanded: false },
    { title: 'Second Item', content: 'Content for second item', expanded: false },
    { title: 'Third Item', content: 'Content for third item', expanded: false }
  ];

  // Define the toggle method here
  toggle(index: number): void {
    this.accordionItems[index].expanded = !this.accordionItems[index].expanded;
  }
}

